// ===== Settings =====
const PBN_API_URL = 'http://pbn-api:3000'; // the API container on the same Docker network
const PAPER_SIZE = 'a4';
const PALETTE = 'darlart-v2';
const DEFAULT_COLORS = 24;
// Shopify line item property / option names (lowercase, matched with "includes")
const PHOTO_PROPERTIES = ['photo', 'image', 'upload', 'fichier'];
const SIZE_OPTIONS = ['size', 'taille', 'format', 'canvas', 'dimension'];
const COLOR_OPTIONS = ['color', 'couleur'];
const ORIENTATION_OPTIONS = ['orientation'];
// ====================

const norm = (s) => String(s || '').trim().toLowerCase();
const findSize = (text) => { const m = String(text || '').match(/(\d{2,3})\s*[x×*]\s*(\d{2,3})/i); return m ? `${m[1]}x${m[2]}` : ''; };
const findColors = (text) => { const m = String(text || '').match(/\b(12|24|36|48)\b/); return m ? Number(m[1]) : 0; };
const findOrientation = (text) => { const t = norm(text); return /paysage|landscape/.test(t) ? 'landscape' : (/portrait/.test(t) ? 'portrait' : ''); };
const base = { apiUrl: PBN_API_URL, paperSize: PAPER_SIZE, palette: PALETTE };
const out = [];

for (const item of $input.all()) {
  // the webhook node wraps the payload in "body"
  const data = item.json.body && item.json.body.orderId ? item.json.body : item.json;

  // Generic payload: { orderId, paid, photoUrl, canvasSize, colors, orientation?, customerEmail? }
  if (data.orderId && !data.line_items) {
    if (data.paid !== true && data.paid !== 'true') continue; // only paid orders
    const canvasSize = findSize(data.canvasSize);
    const issues = [];
    if (!/^https?:\/\//i.test(data.photoUrl || '')) issues.push('missing photo URL');
    if (!canvasSize) issues.push('missing or invalid canvas size');
    out.push({ json: { ...base, orderId: String(data.orderId).replace(/^#/, ''), photoUrl: data.photoUrl || '', canvasSize, colors: findColors(data.colors) || DEFAULT_COLORS, orientation: findOrientation(data.orientation) || 'auto', customerEmail: data.customerEmail || '', ready: issues.length === 0, issues: issues.join(', ') } });
    continue;
  }

  // Shopify order (orders/paid)
  if (data.financial_status !== 'paid') continue;
  const orderId = String(data.name || data.order_number || data.id).replace(/^#/, '');
  const lines = [];
  for (const line of data.line_items || []) {
    const props = (line.properties || []).map((p) => ({ name: norm(p.name), value: String(p.value || '') }));
    const prop = (names) => { const p = props.find((x) => names.some((n) => x.name.includes(n)) && x.value); return p ? p.value : ''; };
    const photo = props.find((x) => PHOTO_PROPERTIES.some((n) => x.name.includes(n)) && /^https?:\/\//i.test(x.value))
      || props.find((x) => /^https?:\/\/\S+\.(jpe?g|png|webp|heic)(\?|$)/i.test(x.value));
    const canvasSize = findSize(prop(SIZE_OPTIONS)) || findSize(line.variant_title) || findSize(line.title);
    if (!photo && !canvasSize) continue; // not a paint by numbers product
    const issues = [];
    if (!photo) issues.push('missing photo upload');
    if (!canvasSize) issues.push('missing or invalid canvas size');
    lines.push({
      ...base,
      product: line.title,
      photoUrl: photo ? photo.value : '',
      canvasSize,
      colors: findColors(prop(COLOR_OPTIONS)) || findColors(line.variant_title) || DEFAULT_COLORS,
      orientation: findOrientation(prop(ORIENTATION_OPTIONS)) || findOrientation(line.variant_title) || 'auto',
      customerEmail: data.email || '',
      ready: issues.length === 0,
      issues: issues.join(', '),
    });
  }
  // one canvas per photo: suffix the order number when an order has several
  lines.forEach((line, index) => out.push({ json: { ...line, orderId: lines.length > 1 ? `${orderId}-${index + 1}` : orderId } }));
}

return out;

// Builds the Claude request that chooses the crop, orientation and difficulty
const order = $('Loop over photos').item.json;
const analysis = $json.error ? null : $json; // POST /v1/analyze response

const [a, b] = order.canvasSize.split('x').map(Number);
const short = Math.min(a, b);
const long = Math.max(a, b);
let orientationRule;
if (short === long) {
  orientationRule = `The canvas is square (${short}x${long} cm, width/height = 1).`;
} else if (order.orientation === 'auto') {
  orientationRule = `Choose the orientation that suits the subject best: portrait (${short}x${long} cm, width/height = ${(short / long).toFixed(3)}) or landscape (${long}x${short} cm, width/height = ${(long / short).toFixed(3)}).`;
} else {
  orientationRule = `The customer ordered a ${order.orientation} canvas, use orientation "${order.orientation}".`;
}

const hints = analysis
  ? [
      `Photo size: ${analysis.width}x${analysis.height} px.`,
      `Automatic detail score: ${analysis.complexity.score.toFixed(2)} on 0-1 (suggests "${analysis.suggestedDifficulty}").`,
      analysis.cropSuggestion ? `Automatic crop suggestion (may cut the subject): ${JSON.stringify(analysis.cropSuggestion.crop)}.` : '',
    ].filter(Boolean).join('\n')
  : 'No automatic analysis is available for this photo.';

const prompt = `You prepare customer photos for Darl'Art paint-by-numbers canvases. The customer ordered a ${order.canvasSize} cm canvas with ${order.colors} paint colors.
${orientationRule}

Decide:
1. crop - the part of the photo to paint, as fractions of the full photo (x, y = top-left corner, w, h = width and height, all between 0 and 1). In pixels its width/height ratio must match the chosen orientation. Keep the main subject whole: never cut through faces, heads, hands or pets, keep a little space around the subject and leave out distracting empty borders.
2. orientation - portrait, landscape (a square canvas can use either).
3. difficulty - easy for simple shapes, flat colors and little depth; medium for moderate detail; hard for detailed or realistic photos (portraits, landscapes, fur, foliage, textures, many small areas).
4. photoQualityWarning - a short reason when the photo is too small, blurry, very dark or unsuitable to paint; otherwise an empty string.
5. reason - one short sentence explaining the crop and difficulty.

${hints}`;

const schema = {
  type: 'object',
  properties: {
    crop: {
      type: 'object',
      properties: { x: { type: 'number' }, y: { type: 'number' }, w: { type: 'number' }, h: { type: 'number' } },
      required: ['x', 'y', 'w', 'h'],
      additionalProperties: false,
    },
    orientation: { type: 'string', enum: ['portrait', 'landscape'] },
    difficulty: { type: 'string', enum: ['easy', 'medium', 'hard'] },
    photoQualityWarning: { type: 'string' },
    reason: { type: 'string' },
  },
  required: ['crop', 'orientation', 'difficulty', 'photoQualityWarning', 'reason'],
  additionalProperties: false,
};

return {
  json: {
    ...order,
    analysis,
    claudeBody: {
      model: 'claude-opus-5',
      max_tokens: 16000,
      // re-runs the request on Anthropic's recommended model if Claude Opus 5 declines it
      fallbacks: 'default',
      output_config: { format: { type: 'json_schema', schema } },
      messages: [
        {
          role: 'user',
          content: [
            { type: 'image', source: { type: 'url', url: order.photoUrl } },
            { type: 'text', text: prompt },
          ],
        },
      ],
    },
  },
};

// Validates Claude's decision; anything invalid falls back to the API's automatic crop / difficulty
const request = $('Build Claude request').item.json;
const response = $json;

let decision = null;
let aiError = '';
if (response.error) {
  aiError = typeof response.error === 'object' ? (response.error.message || JSON.stringify(response.error)) : String(response.error);
} else if (response.stop_reason === 'refusal') {
  aiError = 'Claude declined to analyze the photo';
} else {
  const text = (response.content || []).filter((block) => block.type === 'text').map((block) => block.text).join('');
  try {
    decision = JSON.parse(text);
  } catch (e) {
    aiError = 'the AI answer could not be read';
  }
}

const inRange = (v) => typeof v === 'number' && v >= 0 && v <= 1;
const c = decision && decision.crop;
const crop = c && ['x', 'y', 'w', 'h'].every((k) => inRange(c[k])) && c.w > 0 && c.h > 0 && c.x + c.w <= 1.001 && c.y + c.h <= 1.001
  ? { x: c.x, y: c.y, w: c.w, h: c.h }
  : null;
const difficulty = decision && ['easy', 'medium', 'hard'].includes(decision.difficulty) ? decision.difficulty : 'auto';
const orientation = request.orientation !== 'auto'
  ? request.orientation
  : (decision && ['portrait', 'landscape'].includes(decision.orientation) ? decision.orientation : 'auto');

const warnings = [];
if (aiError) warnings.push(`AI step skipped (${aiError}): automatic crop and difficulty were used`);
if (decision && !crop) warnings.push('the AI crop was invalid: automatic crop was used');
if (decision && decision.photoQualityWarning) warnings.push(`photo quality: ${decision.photoQualityWarning}`);

const { analysis, claudeBody, ...order } = request;
return {
  json: {
    ...order,
    crop,
    difficulty,
    orientation,
    aiReason: decision ? decision.reason : '',
    warning: warnings.join(' | '),
  },
};

// One item per generated file (PDF, SVG, preview, palette)
const job = $('Wait for job').first().json.body;
const order = $('Parse AI decision').first().json;
const folderId = $input.first().json.id;
return job.result.files.map((file) => ({
  json: {
    url: file.url,
    downloadName: file.downloadName,
    folderId,
    orderId: order.orderId,
    difficulty: job.result.difficulty,
    warning: order.warning,
    aiReason: order.aiReason,
  },
}));

